VALUES ('40', '1000', 'LS-NG-MAG_EAD65942601', 'LIMIT_NG', '[불량] MAG_EAD65942601 도통불량', 'MAG_EAD65942601', 'CONTINUITY', 'Y', 2, 'FUNC', TRUNC(SYSDATE), ADD_MONTHS(TRUNC(SYSDATE), 12), 'ACTIVE', 'Y', '통전검사 스테이션', 'admin', SYSTIMESTAMP, '도통 불량 한도견본 — 검사기 결과가 불합격이어야 정상', 'SEED', 'SEED')
